import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Рейды и платные события","description":"","frontmatter":{"pageId":"players/raids-incidents","contentRevision":1},"headers":[],"relativePath":"ru/players/raids-incidents.md","filePath":"ru/players/raids-incidents.md"}'),l={name:"ru/players/raids-incidents.md"};function s(n,a,o,d,c,p){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="реиды-и-платные-события" tabindex="-1">Рейды и платные события <a class="header-anchor" href="#реиды-и-платные-события" aria-label="Permalink to &quot;Рейды и платные события&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Перед рейдом выбери цель, пешек и режим. Snapshot-режим использует копии; реальный режим рискует настоящими пешками. Проверь подтверждение, предупреждение защитнику и правила добычи. Предупреждённый рейд даёт защитнику время (по умолчанию 60 000 тиков); мгновенный сокращает допустимую добычу вдвое.</p><p>Платные события заказываются через доступный серверный каталог. Цена и предупреждение зависят от вида и интенсивности. Сервер проверяет мирный режим, союз, защиту новичка, cooldown и очередь цели. Отмена и отказ обрабатываются через эскроу, а не ручную повторную выдачу.</p><p>Открывай результат операции и почту после рейда: возврат собственных пешек и разрешённая добыча отличаются от произвольного сохранения копии карты.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию: 10 рейдеров, 1 активный рейд, cooldown 8 ч и 24 ч на пару, защита новичка 3 дня, минимум богатства 20 000, добыча 10% с потолком 5 000, похищения выключены. Отключение мирного режима вступает через 24 ч. Союзники не могут заказывать вредные события друг другу.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: живая карта</a></li><li><a href="./visits">Визиты и магазин</a></li><li><a href="./../admins/gameplay-policy">Игровая политика сервера</a></li></ul>',10)])])}const _=e(l,[["render",s]]);export{u as __pageData,_ as default};
